right:
@import 'c/ihStyles';

.intro {
    margin: 0 0 16px;
}
.confirm-lead {
    margin: 0 0 4px;
    font-size: 14px;
}
.cols {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 20px;
    align-items: start;
}
.col {
    min-width: 0;
}
.sec-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    margin-bottom: 6px;
    min-height: 24px;
}
.sec-title {
    margin: 0;
    font-size: 14px;
    font-weight: 700;
    color: var(--ih-ink-2);
}
.gap {
    margin-top: 16px;
}
.copy {
    background: none;
    border: 0;
    padding: 0;
    font: inherit;
    font-size: 13px;
    color: var(--ih-brand);
    cursor: pointer;
}
.copy:hover,
.download:hover {
    text-decoration: underline;
}
.copy:focus-visible {
    outline: 2px solid var(--ih-brand);
    outline-offset: 2px;
}
.download {
    display: inline-block;
    margin-top: 6px;
    font-size: 13px;
    color: var(--ih-brand);
    text-decoration: none;
}
.grid {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
}
.grid th,
.grid td {
    border: 1px solid var(--ih-line);
    padding: 7px 10px;
    text-align: left;
    vertical-align: top;
    overflow-wrap: anywhere;
}
.grid th {
    background: #fafaf9;
    font-weight: 700;
}
.kv th {
    width: 32%;
}
.pre {
    white-space: pre-wrap;
}
.tone {
    font-weight: 700;
}
.tone_ok {
    color: var(--ih-ok);
}
.tone_bad {
    color: var(--ih-bad);
}
.tone_info {
    color: var(--ih-info);
}
.foot {
    display: inline-flex;
    gap: 8px;
}
.retry-line {
    display: flex;
    align-items: center;
    gap: 8px;
    margin: -8px 0 16px;
}
